abstract class PerformanceType {
    abstract double calculateAmount(Performance performance);
    abstract int calculateVolumeCredits(Performance performance);
}

class TragedyPerformance extends PerformanceType {
    @Override
    double calculateAmount(Performance performance) {
        double amount = 40000;
        if (performance.getAudience() > 30) {
            amount += 1000 * (performance.getAudience() - 30);
        }
        return amount;
    }

    @Override
    int calculateVolumeCredits(Performance performance) {
        return Math.max(performance.getAudience() - 30, 0);
    }
}

class ComedyPerformance extends PerformanceType {
    @Override
    double calculateAmount(Performance performance) {
        double amount = 30000;
        if (performance.getAudience() > 20) {
            amount += 10000 + 500 * (performance.getAudience() - 20);
        }
        amount += 300 * performance.getAudience();
        return amount;
    }

    @Override
    int calculateVolumeCredits(Performance performance) {
        return Math.max(performance.getAudience() - 30, 0) + 
               (int)Math.floor(performance.getAudience() / 5);
    }
}

class StatementGenerator {
    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(Locale.US);

    public static String generateStatement(Invoice invoice, Map<String, Play> plays) {
        double totalAmount = 0;
        int volumeCredits = 0;
        StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

        for (Performance perf : invoice.getPerformances()) {
            Play play = plays.get(perf.getPlayID());
            if (play == null) {
                throw new IllegalArgumentException("Unknown play: " + perf.getPlayID());
            }

            PerformanceType performanceType = getPerformanceType(play);
            double thisAmount = performanceType.calculateAmount(perf);
            volumeCredits += performanceType.calculateVolumeCredits(perf);

            result.append(String.format(" %s: %s (%d seats)\n",
                    play.getName(), formatCurrency(thisAmount), perf.getAudience()));
            totalAmount += thisAmount;
        }

        result.append(String.format("Amount owed is %s\n", formatCurrency(totalAmount)));
        result.append(String.format("You earned %d credits\n", volumeCredits));
        return result.toString();
    }

    private static PerformanceType getPerformanceType(Play play) {
        return switch (play.getType()) {
            case "tragedy" -> new TragedyPerformance();
            case "comedy" -> new ComedyPerformance();
            default -> throw new IllegalArgumentException("Unknown type: " + play.getType());
        };
    }

    private static String formatCurrency(double amount) {
        return CURRENCY_FORMAT.format(amount / 100);
    }
